#include "Application.hpp"
#include "MenuText.hpp"
#include "LanguagePatches.hpp"
#include "MenuTextChinese.hpp"
#include <algorithm>
#include <cstdio>
#include <dirent.h>
namespace th075::sdl {
namespace {TextRasterOptions menu_options(u32 width,u32 height,u32 wrap,i32 spacing,bool white=false){TextRasterOptions o;o.width=width;o.height=height;o.wrapWidth=wrap;o.fontHeight=16;o.lineSpacing=spacing;o.lineLimit=40;if(white)o.red=o.green=o.blue=255;return o;}}
void Application::description(u8 index){if(index>=menu_text::options.size())return;std::string value;if(!localized_option_description(index,value))value=FileResources::chinese()?menu_text::chinese_options[index]:menu_text::options[index];prepare_text(menuText,value,menu_options(1024,512,560,10,true));}
void Application::update_music_catalog(){std::string text;const auto flags=profile.selection_unlocks();for(const auto& track:music.catalog.tracks){text+=flags.storyFlags[u8(track.id+100)]?track.title:menu_text::music[0];text+=menu_text::music[1];}prepare_text(musicArtwork.catalog,text,menu_options(1024,1024,560,2));}
void Application::update_title(u8 index){prepare_text(musicArtwork.title,index<music.catalog.tracks.size()?music.catalog.tracks[index].title:menu_text::music[2],menu_options(512,32,560,2));}
void Application::update_details(u8 index){const bool valid=index<music.catalog.tracks.size();prepare_text(musicArtwork.details,valid?music.catalog.tracks[index].description:menu_text::music[3],menu_options(512,512,528,2));std::string credit=menu_text::music[4];if(valid){char no[24];std::snprintf(no,sizeof(no),"No.%02d ",index+1);const auto& t=music.catalog.tracks[index];credit=std::string(no)+t.title+" / "+t.author;}prepare_text(musicArtwork.credit,credit,menu_options(512,32,528,2));}
void Application::load_result_character(u8 id){const auto* d=character_definition(id);if(!d){error="Unknown ranking character";return;}std::vector<u8> bytes;const auto path="data/character/"+std::string(d->name)+"/cardlist.dat";if(!resources.read(id==3?ResourceEdition::Patched:ResourceEdition::Base,path,bytes)||!cards.load(bytes.data(),bytes.size()))error=resources.error+cards.error;}
void Application::update_result_text(bool cardMode){const bool previous=resultList.cardsMode;resultList.cardsMode=cardMode;auto options=menu_options(1024,512,cardMode?640:560,cardMode?16:8,!cardMode);prepare_text(menuText,resultList.text(profile,cards),options);resultList.cardsMode=previous;}
void Application::save_score_name(u8 rank){if(rank<10)profile.selected().ranking[rank].name=profile.workingName;save_scores();}
void Application::choose_replay_name(){saveReplayPath.clear();for(u32 i=0;i<1000;i++){char n[80];std::snprintf(n,sizeof(n),"/save/replay/replay%03u.rep",i);std::vector<u8> bytes;if(!FileResources::read_file(n,bytes)){saveReplayPath=n;break;}}if(saveReplayPath.empty())error="All 1000 replay slots are occupied";}
void Application::save_replay_name(){std::copy(profile.workingName.begin(),profile.workingName.end(),recording.header.begin());std::vector<u8> bytes;if(saveReplayPath.empty()||!recording.encode(bytes)||!FileResources::write_file(saveReplayPath,bytes.data(),u32(bytes.size())))error="Unable to save replay";save_scores();}
bool Application::save_replay(u32 slot,const char* name){if(slot>999||recording.rounds.empty())return false;if(name){std::array<u8,8> encoded;encoded.fill(100);for(u32 i=0;i<8&&name[i];i++){const auto c=u8(name[i]);encoded[i]=c>='A'&&c<='Z'?c-'A':c>='a'&&c<='z'?c-'a'+26:c>='0'&&c<='9'?c-'0'+52:100;}profile.workingName=encoded;}char p[80];std::snprintf(p,sizeof(p),"/save/replay/replay%03u.rep",slot);saveReplayPath=p;save_replay_name();return error.empty();}
void Application::scan_replays(){replays.entries.clear();std::vector<std::string> files;if(auto* directory=opendir("/save/replay")){while(auto* item=readdir(directory)){std::string n=item->d_name;if(n.size()>4&&n.substr(n.size()-4)==".rep"&&n.find('/')==std::string::npos&&n.find(char(92))==std::string::npos)files.push_back(n);}closedir(directory);}std::sort(files.begin(),files.end());for(const auto& file:files){std::vector<u8> bytes;ReplayListing listing;listing.filename="replay/"+file;if(!FileResources::read_file("/save/replay/"+file,bytes)||!listing.replay.load(bytes.data(),bytes.size())||listing.replay.rounds.empty())continue;const auto& h=listing.replay.header;const auto& other=listing.replay.rounds[0].opponentOptions;listing.otherCharacter=other[0];if(h[13]>8||h[10]>10||other[0]>10||h[11]>2||h[12]>2)continue;replays.entries.push_back(std::move(listing));}}
void Application::start_replay(u32 index,u8 round){if(index>=replays.entries.size())return;playback=replays.entries[index].replay;if(round>=playback.rounds.size()){error="Replay stage unavailable";return;}release_battle(true);pendingSession={};pendingRules={};pendingSession.replayMode=2;pendingSession.roundIndex=i8(round+1);playbackCursor=round;pendingSession.replayRound=i8(playback.rounds.size());recordingFinished=false;}
}
